-- Code generated by togo. PostgreSQL query fragment - safe to edit.
-- name: GetAppApmSetting :one
SELECT * FROM app_apm_settings WHERE id = $1;

-- name: ListAppApmSettings :many
SELECT * FROM app_apm_settings ORDER BY created_at DESC LIMIT $1 OFFSET $2;

-- name: CreateAppApmSetting :one
INSERT INTO app_apm_settings (app_id, team_id, enabled, key_hash, key_sealed, created_by)
VALUES ($1, $2, $3, $4, $5, $6)
RETURNING *;

-- name: DeleteAppApmSetting :exec
DELETE FROM app_apm_settings WHERE id = $1;

-- Hosbah queries (MH-575 H7), mirroring app_rum_setting.sql (H5).

-- name: AppApmSettingOfApp :one
SELECT * FROM app_apm_settings WHERE team_id = sqlc.arg('team_id') AND app_id = sqlc.arg('app_id');

-- name: UpsertAppApmSettingKey :one
-- Enable/rotate: one row per app. key_sealed is the plaintext key sealed with the team DEK
-- (crypto.Seal, context internal/apm.EnvSealContext) so a deploy can re-seal it to the target
-- agent's key when auto-wiring OTEL_EXPORTER_OTLP_HEADERS — unlike the RUM key (public, never
-- stored beyond its hash), the APM key is a bearer secret and deploys need it back in the clear.
INSERT INTO app_apm_settings (app_id, team_id, enabled, key_hash, key_sealed, created_by)
VALUES (sqlc.arg('app_id'), sqlc.arg('team_id'), true, sqlc.arg('key_hash'), sqlc.arg('key_sealed'), sqlc.arg('created_by'))
ON CONFLICT (app_id) DO UPDATE SET enabled = true, key_hash = sqlc.arg('key_hash'), key_sealed = sqlc.arg('key_sealed'), updated_at = now()
RETURNING *;

-- name: SetAppApmSettingEnabled :one
-- Toggling off never touches the key: re-enabling without rotating still works with the same
-- deploy env already injected.
UPDATE app_apm_settings SET enabled = sqlc.arg('enabled'), updated_at = now()
WHERE team_id = sqlc.arg('team_id') AND app_id = sqlc.arg('app_id')
RETURNING *;

-- name: AppApmSettingByKeyHash :one
-- tenancy.Scope{TokenHash: ...} (not System), public OTLP ingest endpoints (POST /api/otlp/v1/*,
-- internal/apm): resolves a presented Bearer key to its app and team, and whether APM is enabled.
-- See the RLS policy app_apm_settings_key_hash_select.
SELECT app_id, team_id, enabled FROM app_apm_settings WHERE key_hash = sqlc.arg('key_hash');
